#!/usr/bin/env node
'use strict';

/**
 * prepare-copilot-prompts.js
 *
 * Converts tasks generated by LM Studio into ready-to-paste prompts for
 * GitHub Copilot Chat or the Copilot CLI.
 *
 * Usage:
 *   node scripts/prepare-copilot-prompts.js [--tasks <path-to-tasks.json>]
 *
 * Output:
 *   - copilot-prompts.md  (markdown block with structured prompts)
 *   - copilot-prompts.json (array of { id, title, prompt })
 */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const tmpBase = path.join(root, 'tmp', 'lm-studio-tasks');

function parseArgs(argv) {
  const result = { _: [] };
  for (let i = 0; i < argv.length; i += 1) {
    const fragment = argv[i];
    if (!fragment.startsWith('--')) {
      result._.push(fragment);
      continue;
    }

    const [flag, maybeValue] = fragment.split('=');
    const key = flag.slice(2);
    const next = argv[i + 1];
    if (maybeValue !== undefined) {
      result[key] = maybeValue;
      continue;
    }
    if (next && !next.startsWith('--')) {
      result[key] = next;
      i += 1;
    } else {
      result[key] = true;
    }
  }
  return result;
}

const args = parseArgs(process.argv.slice(2));

function findLatestTasksFile() {
  if (!fs.existsSync(tmpBase)) return null;
  const entries = fs.readdirSync(tmpBase, { withFileTypes: true })
    .filter((dirent) => dirent.isDirectory())
    .map((dirent) => ({
      dirent,
      fullPath: path.join(tmpBase, dirent.name)
    }))
    .filter(({ fullPath }) => fs.existsSync(path.join(fullPath, 'tasks.json')))
    .sort((a, b) => {
      const aTime = fs.statSync(path.join(a.fullPath, 'tasks.json')).mtimeMs;
      const bTime = fs.statSync(path.join(b.fullPath, 'tasks.json')).mtimeMs;
      return bTime - aTime;
    });

  if (entries.length === 0) return null;
  return path.join(entries[0].fullPath, 'tasks.json');
}

function resolveTasksPath() {
  if (args.tasks) {
    const provided = path.isAbsolute(args.tasks) ? args.tasks : path.join(root, args.tasks);
    if (!fs.existsSync(provided)) {
      throw new Error(`Provided tasks file does not exist: ${provided}`);
    }
    return provided;
  }

  const latest = findLatestTasksFile();
  if (!latest) throw new Error('Could not find tasks.json. Run generate-readme-tasks first or supply --tasks.');
  return latest;
}

function loadTasks(tasksPath) {
  const raw = fs.readFileSync(tasksPath, 'utf8');
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error('tasks.json must contain an array.');
    return parsed;
  } catch (err) {
    throw new Error(`Failed to parse tasks file (${tasksPath}): ${err.message}`);
  }
}

function buildPrompt(task) {
  const lines = [];
  lines.push(`You are GitHub Copilot working inside the mnichols08/version-manager repository.`);
  lines.push(`Task ${task.id}: ${task.title}`);
  lines.push('');
  lines.push(`Goal: ${task.summary}`);
  if (Array.isArray(task.acceptanceCriteria) && task.acceptanceCriteria.length) {
    lines.push('Acceptance Criteria:');
    task.acceptanceCriteria.forEach((criterion) => {
      lines.push(`- ${criterion}`);
    });
  }
  if (Array.isArray(task.artifacts) && task.artifacts.length) {
    lines.push('Target Artifacts:');
    task.artifacts.forEach((artifact) => {
      lines.push(`- ${artifact}`);
    });
  }
  lines.push('');
  lines.push('Instructions:');
  lines.push('- Outline your approach before editing.');
  lines.push('- Modify only the files required for this task.');
  lines.push('- Ensure the README remains coherent and update links if sections are renamed or added.');
  lines.push('- Provide a summary of changes and any follow-up suggestions when done.');

  return lines.join('\n');
}

function writeOutputs(tasksPath, tasks, outputs) {
  const outputDir = path.dirname(tasksPath);
  const markdownPath = path.join(outputDir, 'copilot-prompts.md');
  const jsonPath = path.join(outputDir, 'copilot-prompts.json');

  const mdLines = ['# GitHub Copilot Task Prompts', ''];
  outputs.forEach((entry) => {
    mdLines.push(`## ${entry.id} — ${entry.title}`);
    mdLines.push('```');
    mdLines.push(entry.prompt);
    mdLines.push('```');
    mdLines.push('');
  });

  fs.writeFileSync(markdownPath, mdLines.join('\n'), 'utf8');
  fs.writeFileSync(jsonPath, JSON.stringify(outputs, null, 2), 'utf8');
  return { markdownPath, jsonPath };
}

function main() {
  const tasksPath = resolveTasksPath();
  console.log(`Using tasks file: ${tasksPath}`);
  const tasks = loadTasks(tasksPath);

  const outputEntries = tasks.map((task) => ({
    id: task.id || 'UNKNOWN',
    title: task.title || 'Untitled Task',
    prompt: buildPrompt(task)
  }));

  const { markdownPath, jsonPath } = writeOutputs(tasksPath, tasks, outputEntries);
  console.log('Generated Copilot prompt files:');
  console.log(`- ${markdownPath}`);
  console.log(`- ${jsonPath}`);
}

try {
  main();
} catch (error) {
  console.error(error.message || error);
  process.exit(1);
}
